class Solution {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();      // 先修课 -> 后续课
        for (int i = 0; i < numCourses; i++) {
            graph.add(new ArrayList<>());
        }
        int[] indeg = new int[numCourses];                  // 还差几门先修课
        for (int[] p : prerequisites) {                     // 学 p[0] 之前要先学 p[1]：边 p[1] -> p[0]
            graph.get(p[1]).add(p[0]);
            indeg[p[0]]++;
        }
        Deque<Integer> q = new ArrayDeque<>();              // 现在就能学的课
        for (int i = 0; i < numCourses; i++) {
            if (indeg[i] == 0) q.offer(i);
        }
        int[] order = new int[numCourses];
        int k = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            order[k++] = u;
            for (int v : graph.get(u)) {                    // 学完 u，后续课少了一门先修
                if (--indeg[v] == 0) {                      // 先修课都学完了
                    q.offer(v);
                }
            }
        }
        return k == numCourses ? order : new int[0];        // 少了说明有环
    }
}

