func findOrder(numCourses int, prerequisites [][]int) []int {
	graph := make([][]int, numCourses) // 先修课 -> 后续课
	indeg := make([]int, numCourses)   // 还差几门先修课
	for _, p := range prerequisites {  // 学 p[0] 之前要先学 p[1]：边 p[1] -> p[0]
		graph[p[1]] = append(graph[p[1]], p[0])
		indeg[p[0]]++
	}
	q := []int{} // 现在就能学的课
	for i, d := range indeg {
		if d == 0 {
			q = append(q, i)
		}
	}
	order := []int{}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		order = append(order, u)
		for _, v := range graph[u] { // 学完 u，后续课少了一门先修
			indeg[v]--
			if indeg[v] == 0 { // 先修课都学完了
				q = append(q, v)
			}
		}
	}
	if len(order) < numCourses { // 少了说明有环
		return []int{}
	}
	return order
}

