class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        color = [0] * len(graph)                # 0 没走过，1 正在走（在递归栈上），2 安全
        def safe(u: int) -> bool:
            if color[u]:                        # 走过了：1 说明绕回来了，有环
                return color[u] == 2
            color[u] = 1
            for v in graph[u]:
                if not safe(v):                 # 能走到环上，u 也不安全
                    return False
            color[u] = 2                        # 走出去的路都安全
            return True
        return [u for u in range(len(graph)) if safe(u)]

