class Solution {
    private int[] color;                        // 0 没走过，1 正在走（在递归栈上），2 安全
    private List<List<Integer>> graph;

    private boolean safe(int u) {
        if (color[u] != 0) {                    // 走过了：1 说明绕回来了，有环
            return color[u] == 2;
        }
        color[u] = 1;
        for (int v : graph.get(u)) {
            if (!safe(v)) {                     // 能走到环上，u 也不安全
                return false;
            }
        }
        color[u] = 2;                           // 走出去的路都安全
        return true;
    }

    public List<Integer> eventualSafeNodes(List<List<Integer>> graph) {
        this.graph = graph;
        color = new int[graph.size()];
        List<Integer> res = new ArrayList<>();
        for (int u = 0; u < graph.size(); u++) {
            if (safe(u)) res.add(u);
        }
        return res;
    }
}

